import sys

def find_longest_regular_substrings(s):
    n = len(s)
    dp = [0] * (n + 1)
    max_len = 0
    count = 0

    for i in range(1, n + 1):
        if s[i - 1] == ')':
            if i - 2 >= 0 and s[i - 2] == '(':
                dp[i] = dp[i - 2] + 2
            elif i - dp[i - 1] - 1 >= 0 and s[i - dp[i - 1] - 1] == '(':
                dp[i] = dp[i - 1] + 2 + dp[i - dp[i - 1] - 2]

        if dp[i] > max_len:
            max_len = dp[i]
            count = 1
        elif dp[i] == max_len:
            count += 1

    return max_len, count

s = sys.stdin.read().strip()
max_len, count = find_longest_regular_substrings(s)
if max_len == 0:
    print("0 1")
else:
    print(f"{max_len} {count}")
